function mergeCfg(base,over){const o=Object.assign({},base,over||{});o.name=base.name;o.tagline=base.tagline;for(const k of ['act','queue','travel','fuel','challan','regions','states','prices','heroes'])o[k]=Object.assign({},base[k],(over&&over[k])||{});for(const k of ['festivals','events','billboards','changelog','gifts','news'])o[k]=Array.isArray(over&&over[k])?over[k]:base[k];
  // festivals and events added to the defaults in a later update join a saved list once (the admin can still delete them)
  const seen=+((over&&over.defV)||0);if(over&&seen<(base.defV||0))for(const k of ['festivals','events'])if(Array.isArray(over[k])){const names=new Set(over[k].map(f=>f.name));o[k]=over[k].concat((base[k]||[]).filter(f=>(f.v||0)>seen&&!names.has(f.name)));}
  // Beta v2.01.00: the North-East opened; a saved list from before cannot have switched it on
  if(over&&seen<5&&o.regions)o.regions.northeast=true;
  o.defV=Math.max(seen,base.defV||0);return o;}
